for _, c in ipairs(_chunks) do
    local f, err = loadstring(c.src)
    if not f then
        warn("[keyless] COMPILE FAIL " .. c.name .. ": " .. tostring(err))
    else
        local ok, e = pcall(f)
        if not ok then warn("[keyless] RUN FAIL " .. c.name .. ": " .. tostring(e)) end
    end
end
